use crate::models::{ResultWithDefaultError, TimeEntry};
use crate::utilities;
use std::collections::HashMap;

const FIFTEEN_MINUTES: i64 = 15 * 60;
const MINIMUM_ENTRY: i64 = 30 * 60;

pub struct InvoiceCommand;

fn invoice_duration(seconds: i64) -> i64 {
    let seconds = seconds.max(0);
    let rounded =
        (seconds / FIFTEEN_MINUTES + i64::from(seconds % FIFTEEN_MINUTES != 0)) * FIFTEEN_MINUTES;
    rounded.max(MINIMUM_ENTRY)
}

fn invoice_totals(entries: &[TimeEntry]) -> Vec<(String, i64)> {
    let mut totals = HashMap::<String, i64>::new();
    for entry in entries {
        if entry.billable && !entry.is_running() {
            let project = entry
                .project
                .as_ref()
                .map(|project| project.name.clone())
                .unwrap_or_else(|| "No Project".to_string());
            *totals.entry(project).or_default() += invoice_duration(entry.duration);
        }
    }

    let mut totals: Vec<_> = totals.into_iter().collect();
    totals.sort_by(|(left_name, left_seconds), (right_name, right_seconds)| {
        right_seconds
            .cmp(left_seconds)
            .then_with(|| left_name.cmp(right_name))
    });
    totals
}

impl InvoiceCommand {
    pub async fn execute(
        api_client: impl ApiClient,
        since: Option<String>,
        until: Option<String>,
    ) -> ResultWithDefaultError<()> {
        let (since, until) = utilities::normalize_time_entry_list_filters(since, until)?;
        let entries = api_client.get_time_entries_filtered(since, until).await?;
        let totals = invoice_totals(&entries);

        if totals.is_empty() {
            println!("(no data)");
            return Ok(());
        }

        let total: i64 = totals.iter().map(|(_, seconds)| seconds).sum();
        for (project, seconds) in totals {
            println!("{seconds}s  {project}");
        }
        println!("{total}s  Total");
        Ok(())
    }
}

